46	export function DREReport() {
47	  const [open, setOpen] = useState(false);
48	  const [loading, setLoading] = useState(false);
49	  const [stateFilter, setStateFilter] = useState<ReportState>("posted");
50	  const [dateFrom, setDateFrom] = useState(format(new Date(new Date().getFullYear(), new Date().getMonth(), 1), "yyyy-MM-dd"));
51	  const [dateTo, setDateTo] = useState(format(new Date(), "yyyy-MM-dd"));
52	  const [rows, setRows] = useState<DreLineRow[]>([]);
53	  const [unclassified, setUnclassified] = useState<number>(0);
54	  const [topInsumos, setTopInsumos] = useState<TopInsumo[]>([]);
55	
56	  const { stores } = useStore();
57	  const [selectedLojaId, setSelectedLojaId] = useState<string>("all");
58	
59	  const pdfRef = React.useRef<DrePdfGeneratorRef>(null);
60	
61	  // Telemetria
62	  const { trackSearch } = useSearchTelemetry('dre_report');
63	
64	  useEffect(() => {
65	    if (!open) return;
66	    void fetchReport();
67	  }, [open, dateFrom, dateTo, stateFilter, selectedLojaId]);
68	
69	  useEffect(() => {
70	    const filterTerm = `${stateFilter}|${dateFrom}|${dateTo}|${selectedLojaId}`;
71	    trackSearch(filterTerm, rows.length);
72	  }, [stateFilter, dateFrom, dateTo, selectedLojaId, rows.length, trackSearch]);
73	
74	  const fetchReport = async () => {
75	    setLoading(true);
76	    const start = performance.now();
77	    try {
78	      const { resultRows, unclassifiedTotal, topList } = await withTrace('financeiro.dre.fetch', async () => {
79	        // 1. Buscar estrutura DRE: subcontas com suas contas pai
80	        const { data: subaccountsData } = await supabase
81	          .from("finance_mgmt_subaccounts")
82	          .select("id, code, name, nature, account:finance_mgmt_accounts(code, name)")
83	          .eq("active", true);
84	
85	        // Mapa: nome da subconta → estrutura DRE
86	        // (No Financeiro, ao configurar uma conta, categoria recebe o nome da subconta)
87	        const categoryMap = new Map<string, {
88	          accountCode: string; accountName: string;
89	          subCode: string; subName: string; nature: string;
90	        }>();
91	        for (const sub of subaccountsData || []) {
92	          const acct = (sub as any).account;
93	          categoryMap.set(sub.name, {
94	            accountCode: acct?.code || "SEM_CONTA",
95	            accountName: acct?.name || "Sem Conta",
96	            subCode: sub.code,
97	            subName: sub.name,
98	            nature: sub.nature,
99	          });
100	        }
101	
102	        // 2. Buscar transações financeiras (contas a pagar/receber + parcelas) no período
103	        //    Usando a view financial_transactions_unified que já lida com parcelas
104	        let txQuery = supabase
105	          .from("financial_transactions_unified" as any)
106	          .select("valor, valor_juros, tipo, categoria, status, data_vencimento, data_pagamento, loja_id, is_parent")
107	          .eq("is_parent", false)        // Exclui linhas-pai de parcelas (valor=0) → evita duplicação
108	          .neq("status", "cancelado");   // NUNCA incluir cancelados no DRE
109	
110	        // Filtro de período por data_vencimento
111	        txQuery = txQuery.gte("data_vencimento", dateFrom).lte("data_vencimento", dateTo);
112	
113	        // Filtro de status: Realizado (pago), Previsto (pendente/atrasado), Todos
114	        if (stateFilter === "posted") {
115	          txQuery = txQuery.eq("status", "pago");
116	        } else if (stateFilter === "draft") {
117	          txQuery = txQuery.in("status", ["pendente", "atrasado"]);
118	        }
119	        // "all" → todos exceto cancelado (já filtrado acima)
120	
121	        if (selectedLojaId !== "all") {
122	          txQuery = txQuery.eq("loja_id", parseInt(selectedLojaId, 10));
123	        }
124	
125	        // Fetch ALL rows using batch pagination (Supabase limits to 1000 per request)
126	        const BATCH = 1000;
127	        let txData: any[] = [];
128	        let batchFrom = 0;
129	        while (true) {
130	          const { data: batch, error: txError } = await txQuery.range(batchFrom, batchFrom + BATCH - 1);
131	          if (txError) throw txError;
132	          if (!batch || batch.length === 0) break;
133	          txData = txData.concat(batch);
134	          if (batch.length < BATCH) break;
135	          batchFrom += BATCH;
136	        }
137	
